SELECT
  json_extract(value, '$.owner') AS "owner",
  json_extract(value, '$.job') AS "job",
  json_extract(value, '$.limit') AS "limit"
FROM json_each('[{"owner": "1. Task and scorer", "job": "Define the question, tools, expected answer, and grading", "limit": "A grading error can occur even when communication is correct."}, {"owner": "2. Evaluation/model runtime", "job": "Coordinate calls, retry budgets, concurrency, transcript events, and usage", "limit": "Do not assume a direct IModelApi call includes the full runtime."}, {"owner": "3. Provider adapter", "job": "Serialize requests, parse replies, classify failures, translate streams", "limit": "Do not execute a local function merely because a tool call was parsed."}, {"owner": "4. Transport and credential", "job": "Send HTTP/SSE, acquire and refresh bearer tokens", "limit": "Endpoint, audience, version, and headers must match the service."}, {"owner": "5. Foundry deployment", "job": "Serve the selected model and enforce operation support, filters, and quota", "limit": "An adapter cannot create model capabilities or additional quota."}, {"owner": "6. Tool runtime / sandbox", "job": "Execute permitted local tool requests and return results", "limit": "The demo shell is simulated; a command failure need not be a model failure."}]');
